#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <gmssl/sm2.h>

/* Private keys are generated by gmssl sm2keygen, not by this program. */
static int load_key(SM2_KEY *key, const char *path, int private_key)
{
    FILE *fp = fopen(path, "rb");
    const char *pass = getenv("SM2_PASS");
    int ret;
    if (!fp) { perror(path); return 0; }
    if (private_key && !pass) {
        fprintf(stderr, "Set SM2_PASS before reading the private key\n");
        fclose(fp);
        return 0;
    }
    ret = private_key ? sm2_private_key_info_decrypt_from_pem(key, pass, fp)
                      : sm2_public_key_info_from_pem(key, fp);
    fclose(fp);
    return ret == 1;
}

/* Container: ASCII SM2F followed by [2-byte big-endian length | DER] records.
 * Each record encrypts at most 255 bytes; byte order of the plaintext is kept.
 * This simple classroom format is not a standardized authenticated envelope. */
static int crypt_file(const SM2_KEY *key, const char *input,
    const char *output, int encrypt)
{
    FILE *in = fopen(input, "rb"), *out = NULL;
    uint8_t plain[SM2_MAX_PLAINTEXT_SIZE];
    uint8_t cipher[SM2_MAX_CIPHERTEXT_SIZE], header[4];
    size_t n, len, total = 0, blocks = 0;
    int ok = 0;
    if (!in) { perror(input); return 0; }
    out = fopen(output, "wb");
    if (!out) { perror(output); goto end; }
    if (encrypt) {
        if (fwrite("SM2F", 1, 4, out) != 4) goto end;
        while ((n = fread(plain, 1, sizeof(plain), in)) > 0) {
            len = 0;
            if (sm2_encrypt(key, plain, n, cipher, &len) != 1) goto end;
            header[0] = (uint8_t)(len >> 8);
            header[1] = (uint8_t)len;
            if (fwrite(header, 1, 2, out) != 2 ||
                fwrite(cipher, 1, len, out) != len) goto end;
            ++blocks;
            total += n;
            printf("encrypt block %zu: plaintext=%zu, DER=%zu bytes\n", blocks, n, len);
        }
        if (ferror(in)) goto end;
    } else {
        if (fread(header, 1, 4, in) != 4 || memcmp(header, "SM2F", 4)) goto end;
        while ((n = fread(header, 1, 2, in)) > 0) {
            if (n != 2) goto end;
            len = ((size_t)header[0] << 8) | header[1];
            if (len < SM2_MIN_CIPHERTEXT_SIZE || len > sizeof(cipher)) goto end;
            if (fread(cipher, 1, len, in) != len) goto end;
            n = 0;
            if (sm2_decrypt(key, cipher, len, plain, &n) != 1) goto end;
            if (n > sizeof(plain) || fwrite(plain, 1, n, out) != n) goto end;
            ++blocks;
            total += n;
            printf("decrypt block %zu: DER=%zu, plaintext=%zu bytes\n", blocks, len, n);
        }
        if (ferror(in)) goto end;
    }
    if (fclose(out) != 0) { out = NULL; goto end; }
    out = NULL;
    printf("%s: %zu blocks, plaintext total=%zu bytes -> %s\n",
        encrypt ? "encrypt" : "decrypt", blocks, total, output);
    ok = 1;
end:
    fclose(in);
    if (out) fclose(out);
    if (!ok) {
        remove(output);
        fprintf(stderr, "File encryption/decryption failed\n");
    }
    return ok;
}

static int sign_file(const SM2_KEY *key, const char *input, const char *sigpath)
{
    FILE *in = fopen(input, "rb"), *out = NULL;
    SM2_SIGN_CTX ctx;
    uint8_t buf[4096], sig[SM2_MAX_SIGNATURE_SIZE];
    size_t n, siglen = 0, total = 0;
    int ok = 0;
    if (!in) { perror(input); return 0; }
    if (sm2_sign_init(&ctx, key, SM2_DEFAULT_ID, SM2_DEFAULT_ID_LENGTH) != 1)
        goto end;
    while ((n = fread(buf, 1, sizeof(buf), in)) > 0) {
        if (sm2_sign_update(&ctx, buf, n) != 1) goto end;
        total += n;
    }
    if (ferror(in) || sm2_sign_finish(&ctx, sig, &siglen) != 1) goto end;
    out = fopen(sigpath, "wb");
    if (!out) { perror(sigpath); goto end; }
    if (fwrite(sig, 1, siglen, out) != siglen) goto end;
    if (fclose(out) != 0) { out = NULL; goto end; }
    out = NULL;
    printf("sign: %zu bytes, signature=%zu bytes -> %s\n", total, siglen, sigpath);
    ok = 1;
end:
    fclose(in);
    if (out) fclose(out);
    return ok;
}

/* Return 0 for a valid signature, 2 for rejection, and 1 for setup/I/O errors. */
static int verify_file(const SM2_KEY *key, const char *input, const char *sigpath)
{
    FILE *in = NULL, *sf = fopen(sigpath, "rb");
    SM2_VERIFY_CTX ctx;
    uint8_t buf[4096], sig[SM2_MAX_SIGNATURE_SIZE + 1];
    size_t n, siglen, total = 0;
    int ret = 1;
    if (!sf) { perror(sigpath); return 1; }
    siglen = fread(sig, 1, sizeof(sig), sf);
    if (ferror(sf) || siglen == 0 || siglen > SM2_MAX_SIGNATURE_SIZE) goto end;
    in = fopen(input, "rb");
    if (!in) { perror(input); goto end; }
    if (sm2_verify_init(&ctx, key, SM2_DEFAULT_ID, SM2_DEFAULT_ID_LENGTH) != 1)
        goto end;
    while ((n = fread(buf, 1, sizeof(buf), in)) > 0) {
        if (sm2_verify_update(&ctx, buf, n) != 1) goto end;
        total += n;
    }
    if (ferror(in)) goto end;
    ret = sm2_verify_finish(&ctx, sig, siglen) == 1 ? 0 : 2;
    printf("verify: %s, file=%s, bytes=%zu, id=%s\n",
        ret == 0 ? "PASS" : "REJECT", input, total, SM2_DEFAULT_ID);
end:
    if (in) fclose(in);
    fclose(sf);
    return ret;
}

int main(int argc, char **argv)
{
    SM2_KEY key;
    int priv, ret;
    if (argc != 5 || (strcmp(argv[1], "encrypt") && strcmp(argv[1], "decrypt") &&
        strcmp(argv[1], "sign") && strcmp(argv[1], "verify"))) {
        fprintf(stderr, "Usage: %s encrypt|decrypt|sign|verify key.pem input output_or_sig\n", argv[0]);
        return 1;
    }
    priv = !strcmp(argv[1], "decrypt") || !strcmp(argv[1], "sign");
    if (!load_key(&key, argv[2], priv)) return 1;
    if (!strcmp(argv[1], "encrypt")) ret = crypt_file(&key, argv[3], argv[4], 1) ? 0 : 1;
    else if (!strcmp(argv[1], "decrypt")) ret = crypt_file(&key, argv[3], argv[4], 0) ? 0 : 1;
    else if (!strcmp(argv[1], "sign")) ret = sign_file(&key, argv[3], argv[4]) ? 0 : 1;
    else ret = verify_file(&key, argv[3], argv[4]);
    memset(&key, 0, sizeof(key));
    return ret;
}
